class Solution:
    def splitPainting(self, segments: List[List[int]]) -> List[List[int]]:
        lim = max(seg[1] for seg in segments)
        delta = [0] * (lim + 1)
        bound = [False] * (lim + 1)
        for s, e, c in segments:
            delta[s] += c
            delta[e] -= c
            bound[s] = bound[e] = True
        res = []
        cur = 0
        cont = False
        for i in range(lim):
            if bound[i]:
                cur += delta[i]
                cont = False
            if cur > 0:
                if cont and res[-1][1] == i:
                    res[-1][1] = i + 1
                else:
                    res.append([i, i + 1, cur])
                cont = True
        return res

