    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        int lim = 0;
        for (auto& seg : segments) lim = max(lim, seg[1]);
        vector<long long> delta(lim + 1, 0);
        vector<bool> bound(lim + 1, false);
        for (auto& seg : segments) {
            delta[seg[0]] += seg[2];
            delta[seg[1]] -= seg[2];
            bound[seg[0]] = bound[seg[1]] = true;
        }
        vector<vector<long long>> res;
        long long cur = 0;
        bool cont = false;
        for (int i = 0; i < lim; i++) {
            if (bound[i]) {
                cur += delta[i];
                cont = false;
            }
            if (cur > 0) {
                if (cont && res.back()[1] == i) res.back()[1] = i + 1;
                else res.push_back({i, (long long)i + 1, cur});
                cont = true;
            }
        }
        return res;
    }
};

