class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        int lim = 0;
        for (int[] seg : segments) lim = Math.max(lim, seg[1]);
        long[] delta = new long[lim + 1];
        boolean[] bound = new boolean[lim + 1];
        for (int[] seg : segments) {
            delta[seg[0]] += seg[2];
            delta[seg[1]] -= seg[2];
            bound[seg[0]] = true;
            bound[seg[1]] = true;
        }
        List<List<Long>> res = new ArrayList<>();
        long cur = 0;
        boolean cont = false;
        for (int i = 0; i < lim; i++) {
            if (bound[i]) {
                cur += delta[i];
                cont = false;
            }
            if (cur > 0) {
                if (cont && res.get(res.size() - 1).get(1) == i) {
                    res.get(res.size() - 1).set(1, (long) i + 1);
                } else {
                    res.add(new ArrayList<>(Arrays.asList((long) i, (long) i + 1, cur)));
                }
                cont = true;
            }
        }
        return res;
    }
}

