class Solution:
    def splitPainting(self, segments: List[List[int]]) -> List[List[int]]:
        delta = {}
        for s, e, c in segments:
            delta[s] = delta.get(s, 0) + c
            delta[e] = delta.get(e, 0) - c
        res = []
        prev = -1
        cur = 0
        started = False
        for pos in sorted(delta):
            if started and cur > 0:
                res.append([prev, pos, cur])
            cur += delta[pos]
            prev = pos
            started = True
        return res

