class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        TreeMap<Integer, Long> delta = new TreeMap<>();
        for (int[] seg : segments) {
            delta.merge(seg[0], (long) seg[2], Long::sum);
            delta.merge(seg[1], -(long) seg[2], Long::sum);
        }
        List<List<Long>> res = new ArrayList<>();
        long cur = 0;
        long prev = 0;
        boolean started = false;
        for (Map.Entry<Integer, Long> e : delta.entrySet()) {
            if (started && cur > 0) {
                res.add(Arrays.asList(prev, (long) e.getKey(), cur));
            }
            cur += e.getValue();
            prev = e.getKey();
            started = true;
        }
        return res;
    }
}

