var splitPainting = function(segments) {
    const delta = new Map();
    for (const [s, e, c] of segments) {
        delta.set(s, (delta.get(s) || 0) + c);
        delta.set(e, (delta.get(e) || 0) - c);
    }
    const points = [...delta.keys()].sort((a, b) => a - b);
    const res = [];
    let cur = 0, prev = 0, started = false;
    for (const p of points) {
        if (started && cur > 0) res.push([prev, p, cur]);
        cur += delta.get(p);
        prev = p;
        started = true;
    }
    return res;
};
